#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
# Resolve the synaptory CLI that matches this plugin tree.
#
# Search order:
#  1. $SYNAPTORY_CLI_BIN — explicit override (CI, dev loops).
#  2. For a loopback-stamped/local plugin, `synaptory-local` beside the PATH
#     `synaptory`, then on PATH / in the standard user bin directories.
#  3. For every other plugin, `synaptory` on PATH / in the standard user bin
#     directories.
#
# A discovered production-name binary is inspected before use. If it is
# loopback-stamped, resolution fails closed with the issue-#108 remediation
# instead of letting a production plugin ship telemetry to localhost.
#
# A localhost-stamped CLI must not live at the `synaptory` name — that is
# what sent prod-plugin projects to the local stack.

set -euo pipefail

_HOOK_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_ROOT="${PLUGIN_ROOT:-${PLUGIN_ROOT:-$(cd "${_HOOK_DIR}/.." && pwd)}}"
# shellcheck source=./_cp-url.sh
source "${_HOOK_DIR}/_cp-url.sh"

_local_plugin=0
if _synaptory_cp_url_is_local "${_cp_url:-}" || [[ "$PLUGIN_ROOT" == */plugins/local/* ]]; then
  _local_plugin=1
fi

# An explicit override that cannot be used is a configuration error, not a
# reason to go looking elsewhere (#396). The unstamped guard below treats any
# non-empty SYNAPTORY_CLI_BIN as the escape hatch, while the override branch
# further down only fires when the path is `-x`. A missing, stale or
# non-executable value therefore satisfied the guard, skipped the override,
# and fell through to the ordinary production candidate search: an unstamped
# tree with a typo'd override resolved the production CLI and shipped
# telemetry to prod for a project prod has never heard of, which is exactly
# the #320 egress #424 closed for the no-override case.
#
# Refusing here rather than silently searching also matches what the variable
# means: naming a binary is an instruction about WHICH CLI to use, so an
# unusable one is a stop, never a hint.
if [[ -n "${SYNAPTORY_CLI_BIN:-}" ]] && [[ ! -x "${SYNAPTORY_CLI_BIN}" ]]; then
  echo "synaptory: SYNAPTORY_CLI_BIN is set to '${SYNAPTORY_CLI_BIN}' but that is not an executable file; resolving no CLI. Fix the path or unset it." >&2
  exit 1
fi

# An unstamped tree addresses nothing (issue #320). `gate_emitter._resolve_cli`
# already fails closed when no signal names a channel; this resolver did not,
# so a source-tree sideload (`claude --plugin-dir ./plugin-claude`, which the
# multi-runtime demo playbook prescribes) fell through to the production
# `synaptory` on PATH and ran SessionStart's `outbox flush` and
# `telemetry session-start` against prod for a project prod has never heard
# of. "No stamp" is not "production": that fall-through is what stranded 76
# project directories in the outbox over two months.
#
# SYNAPTORY_CLI_BIN remains the explicit escape hatch for CI and e2e runs
# (checked below), and a ~/.cursor/plugins/local sideload keeps its
# local-channel behaviour because it sets _local_plugin above.
if [[ -z "${_cp_url:-}" ]] && [[ "$_local_plugin" == "0" ]] \
   && [[ -z "${SYNAPTORY_CLI_BIN:-}" ]]; then
  echo "synaptory: no control-plane stamp in this plugin tree; resolving no CLI (telemetry skipped, #320). Run ./synaptory deploy local, or set SYNAPTORY_CLI_BIN for CI and e2e runs." >&2
  exit 1
fi

_candidate_url() {
  local candidate="$1" line
  line=$("$candidate" status 2>&1 | sed -n 's/^control_plane_url:[[:space:]]*//p' | head -n1 || true)
  printf '%s' "$line"
}

_validate_candidate() {
  local candidate="$1" explicit="${2:-0}" candidate_url
  candidate_url=$(_candidate_url "$candidate")
  # Explicit overrides are the CI/dev escape hatch. Validate them when they
  # expose an identity, while retaining compatibility with tiny test shims.
  if [[ -z "$candidate_url" ]] && [[ "$explicit" == "1" ]]; then
    return 0
  fi
  if [[ -z "$candidate_url" ]]; then
    echo "synaptory: refusing CLI with unreadable build identity: ${candidate}" >&2
    return 1
  fi
  if [[ "$_local_plugin" == "1" ]]; then
    if ! _synaptory_cp_url_is_local "$candidate_url"; then
      echo "synaptory: refusing production-stamped CLI for local plugin (${candidate_url}). Install the local channel as ~/.local/bin/synaptory-local." >&2
      return 1
    fi
  elif _synaptory_cp_url_is_local "$candidate_url"; then
    cat >&2 <<EOF
synaptory: refusing loopback-stamped CLI for a production plugin (${candidate_url}).
This is the issue #108 local/prod collision. Restore the production CLI:
  curl -fsSL https://synaptory.h3t.co/cli/install.sh | bash
Keep local testing at ~/.local/bin/synaptory-local; do not overwrite synaptory.
EOF
    return 1
  fi
  return 0
}

if [[ -n "${SYNAPTORY_CLI_BIN:-}" ]] && [[ -x "$SYNAPTORY_CLI_BIN" ]]; then
  if _validate_candidate "$SYNAPTORY_CLI_BIN" 1; then
    printf '%s' "$SYNAPTORY_CLI_BIN"
    exit 0
  fi
  exit 1
fi

_candidate=""
if [[ "$_local_plugin" == "1" ]]; then
  if command -v synaptory >/dev/null 2>&1; then
    _prod=$(command -v synaptory)
    [[ -x "$(dirname "$_prod")/synaptory-local" ]] && _candidate="$(dirname "$_prod")/synaptory-local"
  fi
  if [[ -z "$_candidate" ]] && command -v synaptory-local >/dev/null 2>&1; then
    _candidate=$(command -v synaptory-local)
  fi
  for _path in "$HOME/.local/bin/synaptory-local" "$HOME/bin/synaptory-local"; do
    if [[ -z "$_candidate" ]] && [[ -x "$_path" ]]; then _candidate="$_path"; fi
  done
else
  if command -v synaptory >/dev/null 2>&1; then
    _candidate=$(command -v synaptory)
  fi
  for _path in "$HOME/.local/bin/synaptory" "$HOME/bin/synaptory"; do
    if [[ -z "$_candidate" ]] && [[ -x "$_path" ]]; then _candidate="$_path"; fi
  done
fi

if [[ -n "$_candidate" ]] && _validate_candidate "$_candidate"; then
  printf '%s' "$_candidate"
  exit 0
fi

if [[ "$_local_plugin" == "1" ]]; then
  cat >&2 <<'EOF'
synaptory: local CLI not found or its build stamp does not match this plugin.

Build the local channel and install it without replacing production:
  ./synaptory deploy local

Expected binary: ~/.local/bin/synaptory-local
EOF
  exit 1
fi

cat >&2 <<'EOF'
synaptory: CLI not found on $PATH.

The Synaptory CLI is installed separately from the plugin (one prod install
per laptop). Pick the line that matches your OS:

  macOS / Linux:
    curl -fsSL https://synaptory.h3t.co/cli/install.sh | bash

  Windows (PowerShell):
    iwr -useb https://synaptory.h3t.co/cli/install.ps1 | iex

After installing, open a new terminal so $PATH picks up ~/.local/bin
(or %USERPROFILE%\bin on Windows).
EOF
exit 1
